export interface CalaClient {
  getFactsForEra(countryCode: string, startYear: number, endYear: number): Promise<CalaFact[]>;
}

export interface CalaKnowledgeClient {
  knowledgeSearch(query: string): Promise<KnowledgeSearchResult[]>;
}

const CALA_MCP_URL = "https://api.cala.ai/mcp/";

// Matches a leading date/era range like "(c. 50,000 BC - 1,100 BC)" or "(711-1492)".
const TIMELINE_PATTERN = /\(([^()]*?\b(?:BC|AD|century|present)?[^()]*?\d[^()]*?)\)/;

function extractTimeline(text: string): string {
  const match = TIMELINE_PATTERN.exec(text);
  return match ? match[1].trim() : "";
}

function summarize(text: string, maxSentences = 2): string {
  const sentences = text.trim().split(/(?<=[.!?])\s+/);
  return sentences.slice(0, maxSentences).join(" ").trim();
}

export function createCalaKnowledgeClient(apiKey: string): CalaKnowledgeClient {
  return {
    async knowledgeSearch(query: string) {
      const response = await fetch(CALA_MCP_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json, text/event-stream",
          "X-API-KEY": apiKey
        },
        body: JSON.stringify({
          jsonrpc: "2.0",
          id: 1,
          method: "tools/call",
          params: {
            name: "knowledge_search",
            arguments: {
              input: query,
              explainability: true,
              return_entities: true
            }
          }
        })
      });

      if (!response.ok) {
        throw new Error(`Cala MCP request failed: ${response.status} ${response.statusText}`);
      }

      let body = await response.text();

      // The MCP endpoint may respond as SSE ("event: message\ndata: {...}") or plain JSON.
      if (body.trimStart().startsWith("event:")) {
        const dataLines = body
          .split("\n")
          .filter((line) => line.startsWith("data:"))
          .map((line) => line.slice("data:".length).trim());
        body = dataLines[dataLines.length - 1] ?? body;
      }

      const payload = JSON.parse(body);
      if (payload.error) {
        throw new Error(`Cala MCP error: ${JSON.stringify(payload.error)}`);
      }

      const textBlock = payload.result?.content?.find((block: { type: string }) => block.type === "text");
      if (!textBlock) {
        throw new Error("No text content block found in Cala MCP response");
      }

      const toolOutput = JSON.parse(textBlock.text);
      const explainability: Array<{ content: string }> = toolOutput.explainability ?? [];

      return explainability.map((item) => ({
        fact: item.content,
        description: summarize(item.content),
        timeline: extractTimeline(item.content)
      }));
    }
  };
}

