import Link from "next/link";
import { getKnowledgeSearchResults } from "@/lib/knowledge";

export default function KnowledgePage() {
  const { query, results } = getKnowledgeSearchResults();

  return (
    <main className="min-h-screen bg-ink px-6 py-12 text-mist sm:px-10 lg:px-16">
      <Link
        href="/"
        className="inline-block rounded-full border border-white/20 bg-white/5 px-4 py-2 text-sm text-mist transition hover:bg-white/10"
      >
        Back to globe
      </Link>

      <div className="mx-auto mt-10 max-w-4xl">
        <p className="text-xs uppercase tracking-[0.4em] text-gold/80">
          Cala knowledge search
        </p>
        <h1 className="mt-4 font-display text-4xl leading-tight sm:text-5xl">
          {query}
        </h1>

        <div className="mt-12 space-y-6">
          {results.map((result, index) => (
            <div
              key={index}
              className="rounded-[2rem] border border-white/15 bg-white/5 p-6 backdrop-blur-md sm:p-8"
            >
              {result.timeline && (
                <p className="text-sm uppercase tracking-[0.3em] text-gold/80">
                  {result.timeline}
                </p>
              )}
              <p className="mt-4 text-lg leading-8 text-mist sm:text-xl">
                {result.description}
              </p>
              <p className="mt-4 text-sm leading-7 text-mist/70">
                {result.fact}
              </p>
            </div>
          ))}
        </div>
      </div>
    </main>
  );
}

