    queryable_relationships = schema.get("relationships") or {}

    relationship_projection = {}
    if queryable_relationships.get("incoming"):
        relationship_projection["incoming"] = {rel: {} for rel in queryable_relationships["incoming"]}
    if queryable_relationships.get("outgoing"):
        relationship_projection["outgoing"] = {rel: {} for rel in queryable_relationships["outgoing"]}

