def is_implausible_profile(properties: dict, era_start_year: int, era_end_year: int, margin_years: int = 200) -> bool:
    """Flags a retrieved profile as an unreliable match when its own data contradicts
    the era we're building an encyclopedia for - catches cases where Cala has merged
    two unrelated real-world entities under one id (verified to happen: a 16th-century
    author's entity carried an unrelated modern person's imdb_url and aliases)."""
    if property_value(properties, "imdb_url"):
        return True
    birth_date = property_value(properties, "birth_date")
    if birth_date:
        try:
            birth_year = int(str(birth_date)[:4])
        except ValueError:
            birth_year = None
        if birth_year is not None and not (era_start_year - margin_years <= birth_year <= era_end_year + margin_years):
            return True
    return False

