def summarize_markdown(markdown_text: str, max_chars: int = 400) -> str:
    """Extracts the first real prose paragraph from a knowledge_search markdown
    answer (skipping a leading '## Title' heading), for use as a short description."""
    paragraphs = [p.strip() for p in markdown_text.split("\n\n") if p.strip()]
    for paragraph in paragraphs:
        if paragraph.startswith("#"):
            continue
        return paragraph if len(paragraph) <= max_chars else paragraph[:max_chars].rsplit(" ", 1)[0] + "…"
    return markdown_text[:max_chars].strip()


